    h, w = len(grid), len(grid[0])
    wall = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2}
    if all((0, c) in wall for c in range(w)):
        direction = (-1, 0)
    elif all((h - 1, c) in wall for c in range(w)):
        direction = (1, 0)
    elif all((r, 0) in wall for r in range(h)):
        direction = (0, -1)
    elif all((r, w - 1) in wall for r in range(h)):
        direction = (0, 1)
    else:
        raise ValueError("expected a 2-colored border wall")

    remaining = {(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] != 0 and grid[r][c] != 2}
    objects = []
    while remaining:
        seed = remaining.pop()
        color = grid[seed[0]][seed[1]]
        cells = {seed}
        stack = [seed]
        while stack:
            r, c = stack.pop()
            for nr, nc in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                p = (nr, nc)
                if p in remaining and grid[nr][nc] == color:
                    remaining.remove(p)
                    cells.add(p)
                    stack.append(p)
        objects.append((color, cells))

    dr, dc = direction
    if dr < 0:
        objects.sort(key=lambda item: min(r for r, c in item[1]))
    elif dr > 0:
        objects.sort(key=lambda item: -max(r for r, c in item[1]))
    elif dc < 0:
        objects.sort(key=lambda item: min(c for r, c in item[1]))
    else:
        objects.sort(key=lambda item: -max(c for r, c in item[1]))

    out = [[0 for _ in range(w)] for _ in range(h)]
    for r, c in wall:
        out[r][c] = 2
    for color, cells in objects:
        shifted = set(cells)
        while True:
            nxt = {(r + dr, c + dc) for r, c in shifted}
            if any(r < 0 or r >= h or c < 0 or c >= w for r, c in nxt):
                break
            if any(out[r][c] != 0 for r, c in nxt):
                break
            shifted = nxt
        for r, c in shifted:
            out[r][c] = color
    return out
